algorithms.pseudocode:
function SEQUENTIAL_AMPLIFICATION(E, committed, epsilon):
    m <- |E|
    if m = 0: return (0, 0)
    distinct <- count of (u,v) in E with committed[u] != committed[v]
    p <- distinct / m                      # one-round acceptance probability
    if p <= 0: return (1, 0)               # every edge catches the cheat
    if p >= 1: error 'colouring is proper' # nothing to amplify
    k <- max(1, ceil(log(epsilon) / log(p)))
    return (k, p^k)

function REVEAL_BIJECTION(a, b):
    assert a != b
    result <- empty list
    for each pi in permutations of (0,1,2):
        result.append( ((pi[a], pi[b]), pi) )
    return result   # 6 entries, one per permutation; images are the 6 distinct pairs
